\label{hip}
	If  $n/3<s\le n/2$, then 

	\begin{equation}\label{eq:2334}
		\mathrm{ex}(n,s)=\min_k g_k(n,s)\,,
	\end{equation}

	where

	\begin{equation}\label{eq2}
		g_k(n,s)=k(k-1)n^2/2-k(3k-4)ns+(3k-4)(3k-1)s^2/2
	\end{equation}

	for every $k\ge 1$.

\label{fact:1641}
	Let $H$ be an $n$-vertex blow-up of a $k$-regular graph $F$ on the $r$-element 
	vertex set $V(F)=\{v_1, \ldots, v_r\}$. 
	\begin{enumerate}[label=\upshape({\itshape \alph*\,})]
		\item\label{it:1641a} We have 

				\begin{equation}\label{eq:1734}
					\sum_{i=1}^r |N(V_i)|=kn\,.
				\end{equation}

		\item\label{it:1641b} If the blow-up $H$ is proper, then 

		\[
			\delta(H)\le \frac{kn}r \le \Delta(H)\,.
		\]

	\end{enumerate}

\label{l:kregular}
	Let $d, k\ge 2$ be two integers and let $J$ be a graph. Suppose that $J$ has a $k$-regular
	proper blow-up $F$ on $3k-1$ vertices and that $H$ denotes a further proper blow-up of $J$
	having $n$ vertices. If 

	\begin{equation}\label{eq:1710}
		\frac{d+1}{3d+2}n < \delta(H)
		\quad \text{ and } \quad
		\Delta(H) < \frac{d-1}{3d-4}n\,,
	\end{equation}

	then $k=d$.

\label{edges}
	Suppose that $F$ is a $k$-regular graph on $r$ vertices
	and  that $H$ is an $n$-vertex blow-up of $F$ all of whose vertex classes have at 
	least the size $x$. If we have $|N(Z)|\le s$ for every vertex class $Z$ of $H$, then

	\begin{equation}\label{eq:lowx}
		e(H) \le \frac{ns}2 -\frac{x(rs- kn)}2\,.
	\end{equation}

	Moreover, if $rs\neq kn$ and~\eqref{eq:lowx} holds with equality, then  
	\begin{enumerate}
		\item[$\bullet$] at least one vertex class of $H$ has size $x$; 
		\item[$\bullet$] every vertex class $V_i$ of $H$ with $|V_i| > x$
			satisfies $|N(V_i)|=s$.
	\end{enumerate}

The upper bound holds because of

	\begin{align*}
		|V_i| &= |V_0 \cup V_1 \cup \dots \cup V_{3k-2}|+|V_i|-n \\
		&= |N(V_i)| + |N(V_{i+k})|+|N(V_{i-k})|-n 
		\overset{\eqref{eq:inde}}{\le} 3s-n\,.
	\end{align*}

	By applying this estimate to $V_{i+k+1}, \ldots, V_{i+2k-2}$ instead of $V_i$ 
	we infer 

	\begin{align*}
		|V_i| &= n-\bigl(|N(V_{i+(k-1)})|+|N(V_{i-(k-1)})|+
			|V_{i+k+1}|+\dots+|V_{i+2k-2}|\bigr) \\
		&\overset{\eqref{eq:inde}}{\ge} n-\bigl(2s +(k-2)(3s-n)\bigr)= (k-1)n-(3k-4)s\,. \qedhere
	\end{align*}

\label{Vegaup}
	Every vertex $z\in V(\Upsilon_i)$ with $\omega_{\mu\nu} (z)\ge 2$ satisfies		
	\[
		|Z|\le \omega_{\mu\nu}(z)(3s-n)\,.
	\]
	Moreover, we have 
	\begin{align*}	
		|X| + |Y| &\le 2(3s-n)=\omega_{\mu\nu}(\{x, y\})(3s-n) \\
		\text{ and } |V_0| + |V_{2i-1}| &\le 2(3s-n)=\omega_{\mu\nu}(\{v_0, v_{2i-1}\})(3s-n)\,.
	\end{align*}

\label{Vegadown}

	If $z\in V(\Upsilon_i)$, then

	\begin{equation}\label{vegalow}
			|Z|\ge \omega_{\mu\nu}(z)(3s-n)-\lambda\,.
	\end{equation}

As we shall prove by means of a complete case analysis, there exist two adjacent 
	non-neighbours $z'$, $z''$ of $z$ in $\Upsilon^{\mu\nu}_i$ such that each of the sets 
	$\{x, y\}$ and $\{v_0, v_{2i-1}\}$ is either contained in
	$N(z')\cup N(z'')\cup \{z\}$ or in its complement. 

	Once we have two such vertices $z'$ and $z''$, the argument proceeds as follows. 
	Due to $z'z''\in E(\Upsilon_i)$ and $zz', zz''\not\in E(\Upsilon_i)$ the union 
	$R=\{z\}
			\mathbin{\ifx\mathbin\mathop\vphantom{\cup}\fi
				\mathpalette\mov@rlay{\cup\cr\cdot}
			}
			\ifx\mathbin\mathop\expandafter\displaylimits\fi N(z')
			\mathbin{\ifx\mathbin\mathop\vphantom{\cup}\fi
				\mathpalette\mov@rlay{\cup\cr\cdot}
			}
			\ifx\mathbin\mathop\expandafter\displaylimits\fi N(z'')$ is disjoint. 
	Let $S=V(\Upsilon_i)\smallsetminus R$ be 
	the complement of $R$ and write 

	\[
		R_H=Z
			\mathbin{\ifx\mathbin\mathop\vphantom{\cup}\fi
				\mathpalette\mov@rlay{\cup\cr\cdot}
			}
			\ifx\mathbin\mathop\expandafter\displaylimits\fi N(Z')
			\mathbin{\ifx\mathbin\mathop\vphantom{\cup}\fi
				\mathpalette\mov@rlay{\cup\cr\cdot}
			}
			\ifx\mathbin\mathop\expandafter\displaylimits\fi N(Z'')
		\quad \text{ as well as } \quad
		S_H=V(H)\smallsetminus R_H
	\]

	for the sets corresponding to $R$ and $S$ in $H$. Fact~\ref{Vegaup} implies 

	\begin{equation}\label{eq:1831}
		|S_H|\le \omega_{\mu\nu}(S)(3s-n)
	\end{equation}

	and, consequently, we have 

	\begin{align*}
		|Z| &+|N(Z')|+|N(Z'')|
		=
		|R_H|
		=
		n-|S_H| \\
		&\overset{\eqref{eq:1709}}{\ge} 
		\omega_{\mu\nu}\bigl(V(\Upsilon_i)\bigr)(3s-n)-3\lambda-\omega_{\mu\nu}(S)(3s-n) 
		= 
		\omega_{\mu\nu}(R)(3s-n)-3\lambda \\
		&\overset{\eqref{eq:vs}}{\ge} 
		\omega_{\mu\nu}(z)(3s-n)-\lambda+|N(Z')|+|N(Z'')|\,,
	\end{align*}

	i.e., $|Z|\ge \omega_{\mu\nu}(z)(3s-n)-\lambda$. So it remains to check that the auxiliary vertices 
	$z'$ and $z''$ do indeed exist and we list some possible choices in the table that
	follows.

	\begin{center}
	\begin{tabular}{|c|c|c|c|c|c|c|c|c|}
	\hline 
	$z$&  $v_0$&  $v_1, \ldots, v_{2i-2}$&
	$v_{2i-1}$&  $v_{2i}, \ldots, v_{3i-2}, a, v$&  $b, u$&
	$c, w$&  $x$&  $y$ \\ \hline
 	$z'$, $z''$&  $c$, $v$&  $c$, $x$&
	$c$, $u$&  $b$, $u$&  $a$, $v$&
	$v_0$, $v_i$&  $u$, $v_0$&  $a$, $v_0$ \\ \hline 
\end{tabular}
\end{center}
	This concludes the proof of Fact~\ref{Vegadown}.

\label{clm:1315}
	There exists a vertex $z\in V({\Upsilon}_{i}^{\mu\nu})\cap\{x, y, v_0, v_{2i-1}\}$ such that $\omega_{\mu\nu}(z)=1$ and 
	$|Z| = 3s-n-\lambda$.

\label{th:dense}
	Every maximal triangle-free graph on $n$ vertices with minimum degree greater 
	than $n/3$ is a proper blow-up of some Andr\'asfai graph or Vega graph.

Following the proof of Theorem~\ref{thm:main}, we see that~\eqref{eq:0103} 
	holds with equality, for which reason the set $A$ defined in~\eqref{eq:Adef}
	has to be empty. In other words, $G'=G$ and the proof of Theorem~\ref{thm:mindeg}
	discloses that $G'$ is a blow-up of either the Andr\'asfai graph $\Gamma_k$, or of 
   a Vega graph $\Upsilon^{\mu\nu}_i$ with $k=9i-(6+\mu+\nu)$. In the former case, 
   Lemma~\ref{lem:2130} shows that $G$ is isomorphic to a graph in $\mathscr{G}^n_k(s)$
   and in the latter case we apply Lemma~\ref{l:vegaextremal}.

\label{conj:1859}
	If  $n/3<s\le n/2$, then 

	\begin{equation*}                
		\mathrm{ex}(n,s)= \min_k g_k(n,s)\,,
	\end{equation*}

	where $g_k(n,s)$ is defined by~\eqref{eq2}. 

	Moreover, each extremal graph with $\mathrm{ex}(n,s)$ edges is isomorphic to one of the graphs 
	from the families~$\mathscr{G}^n_k(s)$ and~$\mathscr{H}^n_k(s)$ described in the Definitions~\ref{def:exan} 
	and~\ref{def:exvega}, respectively.
